# Kitchen Foundations (cufound): lessons.
LESSONS = {
"kitchen-tour": LES([
 P("Walk into a restaurant kitchen during prep and it can look like chaos. It is not. Every kitchen is built around the same few machines, and every cook has a <b>station</b>: a small area with everything needed for one part of the menu."),
 K("A <b>station</b> is one cook's work area for one kind of food (grill, sauté, fry, cold, pastry). The <b>line</b> is the row of stations that cook during service. The <b>pass</b> is the counter where finished plates are checked before they go to the dining room."),
 TB(["Machine", "How it heats", "Best at"], [
   ["Range (burners or flat-top)", "From below, through a pan", "Sautéing, simmering, sauces"],
   ["Oven (still or convection)", "Hot air all around; a fan moves it faster in a convection oven", "Roasting, baking, braising"],
   ["Broiler and salamander", "Strong heat from above", "Browning tops, melting cheese, finishing"],
   ["Grill (charbroiler)", "Strong heat from below, through grates", "Steaks, vegetables, grill marks"],
   ["Griddle (flat-top)", "A thick hot steel plate", "Eggs, pancakes, burgers, searing"],
   ["Deep fryer", "Hot oil all around", "Fries, battered fish, crisp coatings"],
   ["Combi oven", "Hot air, steam, or both at once", "Roasting with moisture, steaming, holding"],
   ["Walk-in and reach-in refrigerators", "Removes heat", "Keeping food at 41°F or below"],
 ], "The main machines of a commercial kitchen"),
 W("Knowing which way heat comes from tells you what each machine is for. A salamander browns the top of a gratin in a minute because all its heat hits the top; an oven would cook the whole dish through first."),
 EX("Pick the machine", "You need to brown the cheese on top of a bowl of onion soup in under two minutes.", ["The heat must come from above, and fast.", "That is the job of a salamander or broiler."], "A salamander (or broiler)."),
 M("Calling every hot box an oven. A salamander and a broiler heat from above only; a convection oven moves air with a fan, so it cooks faster and browns more evenly than a still oven at the same setting."),
 DRILL("Draw a map of your kitchen at home. Mark where the heat is, where the cold is, where the water is, and where trash goes. Professional kitchens are laid out so food moves in one direction: from storage, to prep, to cooking, to the pass.",
       "Find out where heat comes from in your oven: is there a top element (broiler), a bottom one, a fan?"),
 MP([("kitchen/tools/#appliances", "What's in the Kitchen: appliances", "a picture guide to small appliances at home")]),
 TRY,
], "cia", "g_combi"),

"knives-boards": LES([
 P("Chefs own few knives and know them well. Before you cut, learn the names of the parts. You will hear them in every lesson after this one."),
 K("The parts of a knife: the <b>tip</b> (the front point area, for fine work), the <b>edge</b> (the sharp side), the <b>heel</b> (the back of the edge, for heavy cuts), the <b>spine</b> (the thick top), the <b>bolster</b> (the thick collar between blade and handle on many forged knives), the <b>tang</b> (the part of the blade that runs into the handle) and the <b>handle</b>."),
 TB(["Knife", "Blade", "Main jobs"], [
   ["Chef's knife (French knife)", "8 to 10 inches, curved edge", "Almost everything: chopping, dicing, slicing, mincing"],
   ["Paring knife", "3 to 4 inches", "Peeling, trimming, small work in the hand"],
   ["Serrated (bread) knife", "8 to 10 inches, toothed edge", "Bread, tomatoes, cake layers"],
   ["Boning knife", "5 to 6 inches, narrow", "Taking meat off the bone, trimming"],
   ["Slicer", "Long and narrow", "Carving roasts, slicing salmon"],
   ["Santoku", "About 7 inches, flatter edge", "Like a chef's knife, with more up-and-down chopping"],
 ], "The knives that do most of the work"),
 W("A board that slides is more dangerous than a dull knife. Put a damp towel or a non-slip mat under the board. Use wood or plastic boards: glass, stone and metal destroy edges. Many kitchens color-code plastic boards so raw meat never meets salad."),
 EX("Which knife?", "You need to peel and trim a shallot held in your hand.", ["Small work in the hand needs a short, controllable blade."], "A paring knife."),
 M("Buying a big block of knives. A good chef's knife, a paring knife and a serrated knife do nearly every job; spend the money on those three and a way to keep them sharp."),
 DRILL("Hold your chef's knife and name each part out loud: tip, edge, heel, spine, bolster (if it has one), handle.", "Check your board: put it on the counter and push one corner. If it moves, add a damp towel underneath."),
 MP([("kitchen/tools/#knives", "What's in the Kitchen: knives", "pictures of each knife"), ("kitchen/tools/#boards", "Cutting boards", "wood and plastic, and how to keep them"), ("kitchen/cleaning/#boards", "Cutting boards and cross-contamination", "cleaning boards safely")]),
 TRY,
], "g_knife", "cia"),

"pans-materials": LES([
 P("A pan's job is to move heat from the burner into food. How well it does that depends on what it is made of and how thick it is."),
 K("<b>Conductivity</b> is how fast a metal spreads heat; <b>heat capacity</b> is how much heat a heavy pan stores. Copper and aluminum spread heat fastest; cast iron and carbon steel store a lot and stay hot when food goes in; stainless steel resists acid and rust but spreads heat poorly, so good stainless pans have an aluminum or copper core (<b>clad</b>)."),
 TB(["Material", "Strengths", "Watch out for"], [
   ["Copper (lined with tin or stainless)", "Fastest, most even heat; quick to respond", "Cost; polishing; tin lining wears"],
   ["Aluminum", "Light, cheap, spreads heat well", "Reacts with acid unless coated or anodized"],
   ["Stainless clad", "Durable, no reaction with acid, oven-safe", "Food sticks unless the pan is preheated"],
   ["Cast iron", "Holds heat; great sear; lasts generations", "Heavy; rusts if left wet; season it"],
   ["Carbon steel", "Like cast iron but lighter; restaurant workhorse", "Rusts; must be seasoned"],
   ["Nonstick", "Eggs and fish release easily", "Keep heat moderate; no metal tools; replace when worn"],
 ], "Pan materials"),
 TB(["Shape", "Looks like", "Use"], [
   ["Sauteuse (slope-sided sauté pan)", "Sloped sides", "Tossing food: sautés, omelets"],
   ["Sautoir (straight-sided)", "Straight sides, a lid", "Shallow braises, pan sauces"],
   ["Saucepan", "Tall, one long handle", "Sauces, grains, small batches"],
   ["Rondeau (brazier)", "Wide, shallow, two loop handles", "Braises, browning large batches"],
   ["Stockpot", "Tall and narrow", "Stocks and soups, boiling pasta"],
   ["Sheet pan and hotel pan", "Flat tray; deep rectangular pan", "Roasting, baking; holding and storing food"],
 ], "Pan shapes"),
 W("When cold food hits a thin pan, the pan cools and the food steams. A heavy pan (or a hotter, emptier one) keeps the surface hot enough to brown. That is why restaurants sear in carbon steel or cast iron, and cook in batches."),
 EX("Pick the pan", "You are making a tomato sauce that will simmer for an hour.", ["Tomatoes are acidic.", "Bare aluminum and bare cast iron can react and give a metallic taste.", "Stainless clad (or enameled cast iron) won't react."], "A stainless-clad saucepan or an enameled pot."),
 M("Crowding the pan. If pieces touch, steam can't escape and they boil in their own juices. Leave space, and cook in batches."),
 DRILL("Heat a dry stainless pan for two minutes on medium, then flick in a drop of water. If it skitters around as a ball, the pan is hot enough to sear. Try it at one minute too, and notice the difference.", "Sear two batches of mushrooms: one crowded, one spread out. Compare the color."),
 MP([("kitchen/cookware/", "Cast Iron and Cookware Care", "seasoning, myths and facts, and caring for carbon steel, stainless and nonstick"), ("kitchen/tools/#pans", "Pots and pans", "the shapes, with pictures")]),
 SCI([("/chemistry/chemistry/specific-heat/", "Specific heat", "why a heavy pan stores more heat"), ("/physics/physics-2/conduction-rate/", "Rate of heat conduction", "why copper and aluminum spread heat fast")]),
 TRY,
], "cia"),

"hand-tools": LES([
 P("Professional cooks rely on a few small tools for accuracy and speed. The most important two are the scale and the thermometer."),
 K("<b>Measure what matters.</b> A digital scale (grams and ounces) for ingredients; an instant-read probe thermometer for doneness and food safety; measuring cups and spoons for small amounts. Ladles and portion scoops are sized so every plate gets the same amount."),
 TB(["Tool", "What it is for"], [
   ["Instant-read thermometer", "Checking internal temperature; check it in ice water (32°F) before you trust it"],
   ["Probe or oven thermometer", "Leaves a probe in a roast, or tells you what the oven really is"],
   ["Ladles (2, 4, 6, 8 oz)", "Portioning sauces and soups; the size is stamped on the handle"],
   ["Portion scoops (#8, #12, #16, #20…)", "The number is how many scoops make a quart: a #16 scoop holds 2 fluid ounces"],
   ["Sieve, strainer and chinois", "A chinois is a fine cone strainer for silky sauces and soups"],
   ["Tamis (drum sieve)", "Pushing purées and flour through for smoothness"],
   ["Mandoline", "Even, thin slices; always use the hand guard"],
   ["Microplane (rasp grater)", "Zest, hard cheese, garlic, nutmeg"],
   ["Spider", "A wide wire skimmer for lifting food from oil or water"],
   ["Fish spatula", "Thin, flexible, slotted: turns delicate food"],
   ["Bench scraper", "Moves chopped food, cuts dough, scrapes the board"],
 ], "Small tools every cook uses"),
 W("A portion scoop number is a count, not a size: higher number, smaller scoop. A #8 scoop gives 8 scoops per quart (4 fluid ounces each); a #30 gives 30 (about 1 fluid ounce)."),
 EX("Scoop size", "How many fluid ounces does a #16 scoop hold? (A quart is 32 fluid ounces.)", ["$32 \\div 16 = 2$."], "2 fluid ounces."),
 SAFE("Use the mandoline's hand guard every time, or a cut-resistant glove, as the maker's instructions say. Most mandoline cuts happen on the last few slices.", "Check a thermometer in a glass packed with ice and a little water: it should read 32°F. If it can be adjusted, follow its instructions."),
 M("Trusting an unchecked thermometer. Thermometers drift; a quick ice-water check takes a minute."),
 DRILL("Check your thermometer in ice water. Write down what it reads.", "Use a 2-tablespoon scoop or spoon to portion 12 cookie dough balls, then weigh each one. How close are they?"),
 MP([("kitchen/tools/#measuring", "Measuring tools", "cups, spoons and scales"), ("kitchen/tools/#thermometers", "Thermometers", "the kinds and what each is for"), ("kitchen/food-safety/#thermometer", "Using and checking a food thermometer", "where to put it and how to check it")]),
 TRY,
], "foodcode", "g_combi", "cia"),

"machines": LES([
 P("Machines save hours, and each has habits you need to know. Used wrong, they ruin food or hurt people."),
 K("<b>Stand mixer:</b> the <b>paddle</b> for batters, cookie dough and creaming butter; the <b>whisk</b> for whipping cream and egg whites; the <b>dough hook</b> for bread. <b>Blenders</b> make the smoothest purées; <b>immersion (stick) blenders</b> purée right in the pot; <b>food processors</b> chop, slice and make doughs fast. An <b>immersion circulator</b> heats and stirs a water bath to an exact temperature for sous vide."),
 TB(["Job", "Best machine"], [
   ["Whipped cream, meringue", "Stand mixer with whisk"],
   ["Bread dough", "Stand mixer with dough hook"],
   ["Silky soup or sauce", "Blender (vented), then a chinois"],
   ["Soup right in the pot", "Immersion blender"],
   ["Pie dough, chopping nuts, pesto", "Food processor (pulse)"],
   ["Exact low temperature for hours", "Immersion circulator or combi oven"],
 ]),
 SAFE("Blend hot liquids in small batches, no more than about half full, with the lid's center vent open and covered by a folded towel, as blender makers advise; steam can force a sealed lid off.", "Unplug machines before reaching into a blade or changing attachments, and keep hands out of a running mixer bowl.", "Food processor and blender blades are sharp: lift them out by the center hub."),
 W("A food processor's blade spins fast and heats food; it can turn potato starch to glue and butter in pie dough to grease. Pulse, and stop early."),
 EX("Pick the attachment", "You are creaming butter and sugar for cookies.", ["Creaming beats air into fat with sugar crystals.", "That's the paddle's job; the whisk would clog."], "The paddle."),
 M("Mashing potatoes in a food processor. The blade bursts starch cells and the potatoes turn gluey. Use a ricer, food mill or masher."),
 DRILL("Whip ½ cup of cold cream by hand with a whisk, then the same amount with a mixer. Time both. Stop at soft peaks (the tip flops over) and at stiff peaks (it stands up)."),
 MP([("scratch/whipped-cream/", "Whipped cream", "soft and stiff peaks"), ("scratch/butter/", "Butter", "what happens if you keep whipping")]),
 TRY,
], "cia", "g_sousvide"),

"weighing": LES([
 P("Ask ten people to measure a cup of flour and you'll get ten different weights, from about 120 to 160 grams, depending on how they scoop. Professional recipes avoid that by weighing."),
 K("<b>Weigh dry ingredients.</b> Put the bowl on the scale, press <b>tare</b> (zero), and add the ingredient until you reach the weight. <b>Key conversions:</b> 1 ounce = 28.35 grams; 1 pound = 16 ounces = 453.6 grams; 1 kilogram = 1,000 grams = 2.2 pounds. <b>Fluid ounces</b> measure volume; <b>ounces</b> measure weight. They match only for water and liquids like it."),
 TB(["Volume", "Equals"], [["3 teaspoons", "1 tablespoon"], ["2 tablespoons", "1 fluid ounce"], ["16 tablespoons", "1 cup = 8 fluid ounces"], ["2 cups", "1 pint"], ["4 cups", "1 quart = 32 fluid ounces"], ["4 quarts", "1 gallon"], ["1 cup water", "about 237 milliliters, weighing about 237 grams"]], "U.S. volume measures (NIST)"),
 W("Weighing is faster too: no leveling, fewer dirty cups, and you can scale a recipe by multiplying. Salt is a good example: a tablespoon of fine table salt weighs nearly twice as much as a tablespoon of flaky kosher salt, so recipes in grams avoid oversalting."),
 EX("Ounces to grams", "A recipe calls for 12 ounces of butter. How many grams?", ["$12 \\times 28.35 = 340.2$."], "About 340 grams."),
 EX("Grams to pounds", "You have 2,500 grams of potatoes. How many pounds?", ["$2500 \\div 453.6 \\approx 5.51$."], "About 5.5 pounds."),
 M("Measuring honey or oil in fluid ounces and calling it weight. A cup of honey weighs about 12 ounces, not 8."),
 DRILL("Scoop a cup of flour straight from the bag and weigh it. Then spoon flour into the cup and level it, and weigh again. Write down both weights.", "Weigh a level tablespoon of table salt and one of kosher salt."),
 MP([("kitchen/know-how/#measure", "Measurements and conversions", "a full table"), ("guides/differences/#salt", "Table, kosher and sea salt", "why they measure differently")]),
 TRY,
], "nist"),

"reading-recipes": LES([
 P("A recipe is a plan written by someone else. Read it like a cook: twice, all the way through, before you touch anything."),
 K("<b>Read for:</b> the yield, the equipment, the times (including resting and chilling), the temperatures, and the steps that must start early. <b>To scale</b>, find the <b>conversion factor</b> = new yield ÷ old yield, and multiply every ingredient by it."),
 V("cu-scale", None, "Type a new yield and watch every amount change. Pans, cooking times and seasoning need your judgment."),
 W("Multiplying is the easy part. Bigger batches need bigger pans and may cook longer; a pot that is twice as wide doesn't take twice the time. Strong flavors (salt, spice, chile) and leaveners are often added at a little less than the full factor, then adjusted by tasting."),
 EX("Scale up", "A soup serves 6 and uses 900 g of carrots. You need 20 servings.", ["Factor: $20 \\div 6 \\approx 3.33$.", "Carrots: $900 \\times 20 \\div 6 = 3000$ g."], "3,000 g (3 kg) of carrots."),
 EX("Scale down", "A dough recipe makes 24 rolls with 1,200 g flour. You want 8 rolls.", ["Factor: $8 \\div 24 = \\tfrac{1}{3}$.", "$1200 \\times \\tfrac{1}{3} = 400$ g."], "400 g of flour."),
 M("Scaling by adding instead of multiplying, such as adding 2 to every amount to make \"a bit more\". Ratios break and the recipe fails."),
 DRILL("Pick a recipe from Meal Prep and write its plan: what must start first, what can wait, when the oven goes on.", "Halve a cookie recipe on paper, then bake it. Did anything need adjusting (an egg, the baking time)?"),
 MP([("kitchen/know-how/#recipes", "How to read a recipe", "the parts of a recipe"), ("recipes/", "Recipes", "every recipe there scales to your household")]),
 TRY,
], "cia", "nist"),

"mise-en-place": LES([
 P("Mise en place (meez on plahs) is French for \"putting in place\". It means everything you need is ready before the heat goes on. Chefs treat it as a habit of mind, not just a tray of chopped onions."),
 K("<b>Mise en place, step by step:</b> read the recipe; write a short list in order; gather the tools; gather and measure the ingredients; do the prep (wash, peel, cut, measure); set your station so the things you use most are closest. Then <b>work clean</b>: wipe as you go, keep a towel and a trash bowl handy, and put things back."),
 LI("Things that take longest start first (stock, dough, chilling, marinating).",
    "Group ingredients by when they go in: \"first in the pan\", \"after 5 minutes\", \"at the end\".",
    "Keep raw meat prep separate from ready-to-eat food, and clean between.",
    "A clean station is a safe station: no clutter around the knife and no towels near the flame."),
 W("Once food is in a hot pan, you have no time to look for things. A sauté takes seconds; garlic burns in under a minute. Mise en place turns cooking into putting together parts you already have."),
 EX("What first?", "Tonight's dinner: rice (20 minutes plus 10 to rest), a chicken stir-fry (8 minutes of cooking), and cut vegetables (15 minutes of prep). What do you start first?", ["Rice takes longest and holds well.", "Start the rice, prep vegetables and chicken while it cooks, then stir-fry at the end."], "The rice."),
 M("Starting to cook and then chopping. The pan overheats, the garlic burns, and the meat overcooks while you hunt for the soy sauce."),
 DRILL("Before your next meal, set out every ingredient measured in small bowls before you turn on the stove. Time how long the cooking takes compared with your usual way.", "Keep a damp towel at your station and wipe the board between each ingredient."),
 MP([("plan/", "Meal Prep planner", "plan a week's cooking in order")]),
 TRY,
], "g_mise", "cia"),
}
